#!/usr/bin/env node
/**
 * Seed users exactly as the app's Stripe `checkout.session.completed` webhook
 * handler (app/api/webhooks/stripe/route.ts) leaves them after a successful
 * subscription checkout:
 *
 *   db.user.update({
 *     where: { id: session.metadata.userId },
 *     data: {
 *       stripeSubscriptionId: subscription.id,
 *       stripeCustomerId: subscription.customer,
 *       stripePriceId: subscription.items.data[0].price.id,
 *       stripeCurrentPeriodEnd: new Date(subscription.current_period_end * 1000),
 *     },
 *   })
 *
 * The webhook only ever *updates* an existing user (it never creates one), so
 * here we upsert keyed on email: create the user if missing (as the app's
 * sign-in flow would), then apply the same stripe fields the webhook writes.
 *
 * Usage: cd /root/app && node /root/mq/seed.js /root/mq/seed.json
 */
const fs = require("fs")
const path = require("path")

const APP_DIR = "/root/app"

// --- Load DATABASE_URL from /root/app/.env without printing secrets ---------
function loadEnv(appDir) {
  const envPath = path.join(appDir, ".env")
  if (!fs.existsSync(envPath)) return
  const raw = fs.readFileSync(envPath, "utf8")
  for (const line of raw.split(/\r?\n/)) {
    const m = line.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/)
    if (!m) continue
    const key = m[1]
    let val = m[2].trim()
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1)
    }
    if (process.env[key] === undefined) process.env[key] = val
  }
}

loadEnv(APP_DIR)

if (!process.env.DATABASE_URL) {
  console.error("ERROR: DATABASE_URL not found in /root/app/.env")
  process.exit(1)
}

// Use the app's own ORM client.
const { PrismaClient } = require(path.join(APP_DIR, "node_modules/@prisma/client"))
const db = new PrismaClient()

function toDateOrNull(seconds) {
  if (seconds === null || seconds === undefined || seconds === "") return null
  const n = Number(seconds)
  if (!Number.isFinite(n)) throw new Error(`Invalid unix seconds: ${seconds}`)
  // Webhook: new Date(subscription.current_period_end * 1000)
  return new Date(n * 1000)
}

async function seedUser(entry) {
  const { email, name, stripeCustomerId, stripeSubscriptionId, stripePriceId, stripeCurrentPeriodEnd } = entry
  if (!email) throw new Error("entry missing email")

  const stripeData = {
    stripeCustomerId: stripeCustomerId ?? null,
    stripeSubscriptionId: stripeSubscriptionId ?? null,
    stripePriceId: stripePriceId ?? null,
    stripeCurrentPeriodEnd: toDateOrNull(stripeCurrentPeriodEnd),
  }

  // Create-or-find the user by email (email is @unique), then apply the exact
  // fields the checkout webhook writes.
  const user = await db.user.upsert({
    where: { email },
    create: {
      email,
      name: name ?? null,
      ...stripeData,
    },
    update: {
      ...(name !== undefined ? { name } : {}),
      ...stripeData,
    },
  })

  return user
}

async function main() {
  const file = process.argv[2]
  if (!file) {
    console.error("Usage: node /root/mq/seed.js <seed.json>")
    process.exit(1)
  }
  const entries = JSON.parse(fs.readFileSync(file, "utf8"))
  if (!Array.isArray(entries)) throw new Error("seed file must be a JSON array")

  const results = []
  for (const entry of entries) {
    const u = await seedUser(entry)
    results.push({
      id: u.id,
      email: u.email,
      name: u.name,
      stripeCustomerId: u.stripeCustomerId,
      stripeSubscriptionId: u.stripeSubscriptionId,
      stripePriceId: u.stripePriceId,
      stripeCurrentPeriodEnd: u.stripeCurrentPeriodEnd
        ? u.stripeCurrentPeriodEnd.toISOString()
        : null,
    })
  }
  console.log(JSON.stringify(results, null, 2))
}

main()
  .catch((e) => {
    console.error("SEED FAILED:", e.message)
    process.exitCode = 1
  })
  .finally(async () => {
    await db.$disconnect()
  })

