/**
 * Print a Cookie header value that authenticates as an existing user.
 *
 * Usage: cd /root/app && node /root/mq/session.js <email>
 *
 * Mirrors the app's own auth setup (lib/auth.ts): NextAuth with
 * session.strategy = "jwt", so the session is a JWE produced by
 * next-auth/jwt encode() with NEXTAUTH_SECRET, stored in the
 * `next-auth.session-token` cookie (plain http => non-secure cookie name).
 */
const fs = require("fs")
const path = require("path")

const APP_DIR = "/root/app"

// --- Load /root/app/.env without printing secrets ---------------------------
function loadEnv(appDir) {
  const envPath = path.join(appDir, ".env")
  if (!fs.existsSync(envPath)) return
  const raw = fs.readFileSync(envPath, "utf8")
  for (const line of raw.split(/\r?\n/)) {
    const m = line.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/)
    if (!m) continue
    const key = m[1]
    let val = m[2].trim()
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1)
    }
    if (process.env[key] === undefined) process.env[key] = val
  }
}

loadEnv(APP_DIR)

const email = process.argv[2]
if (!email) {
