const { encode } = require(path.join(APP_DIR, "node_modules/next-auth/jwt"))
const { PrismaClient } = require(path.join(APP_DIR, "node_modules/@prisma/client"))
const db = new PrismaClient()

async function main() {
  const user = await db.user.findUnique({ where: { email } })
  if (!user) {
    console.error(`ERROR: no user with email ${email}`)
    process.exit(1)
  }

  // Same shape the app's jwt callback returns (id/name/email/picture).
  const token = {
    id: user.id,
    name: user.name,
    email: user.email,
    picture: user.image,
